def snapshot():
    return {name:hashlib.sha256((ROOT/name).read_bytes()).hexdigest() for name in (*SOURCES,*OWN,PREFIX+'pins.json')}

def check():
    pins=json.loads((HERE/'pins.json').read_bytes())
    if type(pins) is not dict or set(pins)!={'schema','profile','sources','own'} or type(pins['schema']) is not int or pins['schema']!=1 or pins['profile']!='attention-bank-m16-fraction-calibration-v1':raise ValueError('source contract')
    if set(pins['sources'])!=set(SOURCES) or set(pins['own'])!=set(OWN):raise ValueError('source inventory')
    for group in ('sources','own'):
        for name,digest in pins[group].items():
            if hashlib.sha256((ROOT/name).read_bytes()).hexdigest()!=digest:raise ValueError('source drift')
    from ..attention_bank_scratch.check_sources import check as base_check
    base_check()
    return dict(status='PASS_SOURCE_ONLY',sources=len(SOURCES),own=len(OWN),m128_enabled=False,native_enabled=False)

if __name__=='__main__':print(json.dumps(check(),sort_keys=True))
